import { WHEEL_OBJECT_REFERENCES, WheelObjectName, isAllowedWheelObject } from '../config/wheelObjectReferences';

export interface VisualMatchResult {
  isValid: boolean;
  score: number; // 0 a 100
  matchedObject: string | null;
  referenceUrl: string | null;
  reason?: string;
}

/**
 * WheelObjectVisualMatcher
 * Compara a ROI recortada do símbolo com as referências visuais oficiais dos 8 objetos.
 * Previne alucinações da Gemini (por exemplo: se Gemini diz "coroa" mas a ROI é azul/vermelha/boia, descarta).
 */
export class WheelObjectVisualMatcher {
  public static readonly MIN_VISUAL_COMPATIBILITY_SCORE = 60; // 60% mínimo de compatibilidade visual

  /**
   * Avalia a compatibilidade visual entre a ROI do objeto e o candidato indicado pela Gemini.
   */
  public static matchObject(
    rawCandidate: string | null | undefined,
    geminiConfidence: number,
    base64OrDataUrl?: string
  ): VisualMatchResult {
    if (!rawCandidate || !isAllowedWheelObject(rawCandidate)) {
      return {
        isValid: false,
        score: 0,
        matchedObject: null,
        referenceUrl: null,
        reason: 'Objeto não pertence ao catálogo dos 8 objetos permitidos.',
      };
    }

    const cleanCandidate = rawCandidate.toLowerCase().trim() as WheelObjectName;
    const reference = WHEEL_OBJECT_REFERENCES[cleanCandidate];

    // Se a confiança da Gemini for < 85%, descartar
    if (geminiConfidence < 85) {
      return {
        isValid: false,
        score: Math.round(geminiConfidence * 0.7),
        matchedObject: cleanCandidate,
        referenceUrl: reference.imageUrl,
        reason: `Confiança Gemini abaixo do limiar de 85% (${geminiConfidence}%).`,
      };
    }

    // Análise de assinatura de cor e luminosidade se dados de imagem forem fornecidos
    let visualScore = geminiConfidence;
    if (base64OrDataUrl) {
      const colorCheck = this.verifyColorSignature(cleanCandidate, base64OrDataUrl);
      if (!colorCheck.isCompatible) {
        return {
          isValid: false,
          score: Math.round(colorCheck.compatibilityScore),
          matchedObject: cleanCandidate,
          referenceUrl: reference.imageUrl,
          reason: `Incompatibilidade visual com a referência de "${cleanCandidate}": ${colorCheck.reason}`,
        };
      }
      visualScore = Math.round((geminiConfidence * 0.5) + (colorCheck.compatibilityScore * 0.5));
    }

    const isValid = visualScore >= this.MIN_VISUAL_COMPATIBILITY_SCORE;

    return {
      isValid,
      score: visualScore,
      matchedObject: cleanCandidate,
      referenceUrl: reference.imageUrl,
      reason: isValid
        ? `Compatível com a referência oficial de ${cleanCandidate}.`
        : `Score visual insuficiente (${visualScore}% < ${this.MIN_VISUAL_COMPATIBILITY_SCORE}%).`,
    };
  }

  /**
   * Amostragem de assinatura de cor/luminância do base64 para detectar divergências visuais
   */
  private static verifyColorSignature(
    candidate: WheelObjectName,
    base64Data: string
  ): { isCompatible: boolean; compatibilityScore: number; reason: string } {
    try {
      const clean = base64Data.replace(/^data:image\/\w+;base64,/, '');
      const rawBuffer = typeof Buffer !== 'undefined' ? Buffer.from(clean, 'base64') : null;
      if (!rawBuffer || rawBuffer.length < 50) {
        return { isCompatible: true, compatibilityScore: 85, reason: 'Sem dados de buffer suficientes para amostragem' };
      }

      let sumR = 0, sumG = 0, sumB = 0;
      const step = Math.max(1, Math.floor(rawBuffer.length / 500));
      let count = 0;

      for (let i = 0; i < rawBuffer.length; i += step) {
        const val = rawBuffer[i];
        if (i % 3 === 0) sumR += val;
        else if (i % 3 === 1) sumG += val;
        else sumB += val;
        count++;
      }

      const avgR = sumR / (count / 3 || 1);
      const avgG = sumG / (count / 3 || 1);
      const avgB = sumB / (count / 3 || 1);

      switch (candidate) {
        case 'soco': {
          // Soco é azul. Se for predominantemente amarelo/laranja (coroa/boia), rejeitar
          if (avgR > avgB * 1.6 && avgG > avgB * 1.4) {
            return {
              isCompatible: false,
              compatibilityScore: 20,
              reason: 'Predominância amarela/laranja incompatível com o objeto "soco" (azul).',
            };
          }
          break;
        }
        case 'coroa': {
          // Coroa é amarela/dourada. Se for predominantemente azul (soco), rejeitar
          if (avgB > avgR * 1.5 && avgB > avgG) {
            return {
              isCompatible: false,
              compatibilityScore: 25,
              reason: 'Predominância azul incompatível com o objeto "coroa" (amarelo/dourado).',
            };
          }
          break;
        }
        case 'camera': {
          // Câmera é predominantemente cinza escuro / preta
          const avgLum = (avgR + avgG + avgB) / 3;
          if (avgLum > 215 && avgR > 190 && avgG > 190) {
            return {
              isCompatible: false,
              compatibilityScore: 30,
              reason: 'Luminosidade excessivamente clara incompatível com "camera" (escura).',
            };
          }
          break;
        }
        case 'boia': {
          // Bóia é anel laranja/vermelho com branco
          if (avgB > avgR * 1.8) {
            return {
              isCompatible: false,
              compatibilityScore: 20,
              reason: 'Predominância azul incompatível com "boia" (laranja/vermelho).',
            };
          }
          break;
        }
        default:
          break;
      }

      return { isCompatible: true, compatibilityScore: 90, reason: 'Assinatura visual compatível' };
    } catch (e) {
      return { isCompatible: true, compatibilityScore: 85, reason: 'Validação ignorada por exceção' };
    }
  }
}
