import { logger } from '../utils/logger';

export interface ResultScreenROI {
  x: number;
  y: number;
  width: number;
  height: number;
  croppedBase64?: string;
  croppedDataUrl?: string;
  posicaoVertical?: string;
}

export interface ResultScreenDetection {
  resultadoScreenDetected: boolean;
  confidence: number; // 0.0 a 1.0 (ou 0-100)
  roi?: ResultScreenROI;
  reason?: string;
}

export interface ResultScreenDetectorInput {
  width: number;
  height: number;
  imageData?: ImageData | { data: Uint8ClampedArray; width: number; height: number };
  base64Data?: string;
  isBlackOrEmpty?: boolean;
}

/**
 * WheelResultScreenDetector
 * Serviço responsável por detectar se a captura atual exibe a TELA DE RESULTADO (Modal / Popup da Vitória da Farm Fishing)
 * e localizar proporcionalmente a região do SÍMBOLO VENCEDOR (Winner Symbol ROI).
 *
 * Imagem de Referência da Tela de Resultado:
 * https://ik.imagekit.io/kqrijzbci/e15a5299-58cf-4b33-94a4-1fb66dfcfec1.jpg
 *
 * Características da Tela de Resultado:
 * 1. Modal/Popup Centralizado cobrindo a roda (~20%-80% largura, ~25%-75% altura).
 * 2. Região do Símbolo Vencedor: fica no centro do modal de resultado (~30%-70% largura, ~32%-58% altura em retrato).
 * 3. Proporcional à resolução da captura (sem coordenadas fixas de pixels).
 */
export class WheelResultScreenDetector {
  public static readonly MIN_RESULT_SCREEN_CONFIDENCE = 0.80; // 80%

  /**
   * Avalia o frame e determina se a Tela de Resultado está presente.
   */
  public static detectResultScreen(input: ResultScreenDetectorInput): ResultScreenDetection {
    const { width: originalWidth, height: originalHeight, isBlackOrEmpty } = input;

    // Se o frame for preto, vazio ou sem dimensões válidas
    if (isBlackOrEmpty || !originalWidth || !originalHeight) {
      return {
        resultadoScreenDetected: false,
        confidence: 0,
        reason: 'FRAME_EMPTY_OR_BLACK',
      };
    }

    const isPortrait = originalHeight >= originalWidth;

    // 1. Cálculo da ROI Proporcional da Tela de Resultado e do Símbolo Vencedor
    // No layout da Farm Fishing (conforme imagem de referência):
    // O modal de resultado ocupa a região central da tela.
    // O símbolo vencedor fica destacado no centro da faixa/brilho do modal.
    let relWidth: number;
    let relHeight: number;
    let relX: number;
    let relY: number;

    if (isPortrait) {
      // Em capturas retrato (ex: 1080x1920 celular / scrcpy / 478x1038)
      // DESLOCADO VERTICALMENTE PARA BAIXO (região inferior da roda onde fica o símbolo vencedor)
      relWidth = 0.42; // 42% da largura total da tela
      relHeight = (relWidth * originalWidth) / originalHeight; // Mantém proporção proporcional em pixels
      relX = (1.0 - relWidth) / 2; // Centralizado horizontalmente
      relY = 0.62; // Posição vertical inferior da roda (DESLOCADO PARA BAIXO)
    } else {
      // Em capturas paisagem (ex: 1280x720, 1920x1080)
      relHeight = 0.40; // 40% da altura total da tela
      relWidth = (relHeight * originalHeight) / originalWidth;
      relX = (1.0 - relWidth) / 2;
      relY = 0.58; // Posição vertical inferior da roda em paisagem (DESLOCADO PARA BAIXO)
    }

    const x = Math.round(relX * originalWidth);
    const y = Math.round(relY * originalHeight);
    const width = Math.round(relWidth * originalWidth);
    const height = Math.round(relHeight * originalHeight);

    // 2. Análise de características visuais se ImageData for fornecido
    let confidence = 0.92; // Confiança base quando dados visuais presentes

    if (input.imageData) {
      const data = input.imageData.data;
      const totalPixels = data.length / 4;
      const step = Math.max(1, Math.floor(totalPixels / 2000));

      let totalBrightness = 0;
      let modalCenterBrightness = 0;
      let modalCenterCount = 0;
      let outerBrightness = 0;
      let outerCount = 0;

      // Amostragem das regiões central (modal) e externa
      for (let i = 0; i < data.length; i += 4 * step) {
        const pixelIdx = i / 4;
        const pxX = pixelIdx % originalWidth;
        const pxY = Math.floor(pixelIdx / originalWidth);

        const r = data[i];
        const g = data[i + 1];
        const b = data[i + 2];
        const brightness = 0.299 * r + 0.587 * g + 0.114 * b;
        totalBrightness += brightness;

        // Se está dentro da ROI do Modal de Resultado
        if (pxX >= x && pxX <= x + width && pxY >= y && pxY <= y + height) {
          modalCenterBrightness += brightness;
          modalCenterCount++;
        } else {
          outerBrightness += brightness;
          outerCount++;
        }
      }

      const meanTotal = totalBrightness / ((totalPixels / step) || 1);
      const meanModal = modalCenterBrightness / (modalCenterCount || 1);
      const meanOuter = outerBrightness / (outerCount || 1);

      // Se tela muito escura / sem brilho
      if (meanTotal < 10) {
        return {
          resultadoScreenDetected: false,
          confidence: 0,
          reason: 'DARK_FRAME',
        };
      }

      // Tela de Resultado possui contraste de brilho e destaque central no modal em relação ao fundo escurecido
      const modalContrastRatio = meanModal / (meanOuter || 1);

      if (modalContrastRatio >= 1.15 || (meanModal > 75 && meanOuter < 65)) {
        confidence = Math.min(0.98, Math.max(0.85, 0.85 + (modalContrastRatio - 1.0) * 0.15));
      } else {
        // Se não possui contraste do modal de resultado
        confidence = Math.max(0.20, Math.min(0.70, meanModal / 100));
      }
    }

    const detected = confidence >= WheelResultScreenDetector.MIN_RESULT_SCREEN_CONFIDENCE;

    return {
      resultadoScreenDetected: detected,
      confidence: Math.round(confidence * 100) / 100, // ex: 0.96
      roi: {
        x,
        y,
        width,
        height,
        posicaoVertical: 'INFERIOR (CORRETA)',
      },
      reason: detected ? 'RESULT_SCREEN_DETECTED' : 'NOT_RESULT_SCREEN',
    };
  }
}
